// Change detection and the watchdog live in the repo: automation/watcher/.
// Output 1: an alert for Claude. Output 2: a watchdog notice for #mod-alerts.
const watcher = global.get('watcher')
if (!watcher) {
  node.error('Watcher not loaded: set AIM_ASSIST_WATCHER in ~/.node-red/.env and restart', msg)
  return null
}
const time = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })
const ok = msg.statusCode === 200 && Array.isArray(msg.payload?.entries)

const watchKey = `watchdog_${msg.view}`
const watch = watcher.trackFetch(flow.get(watchKey, 'file'), ok)
flow.set(watchKey, watch.state, 'file')
const post = watch.notice && watcher.watchdogPost(watch.notice, {
  view: msg.view,
  failures: watch.state.failures,
  status: msg.statusCode,
})
const notice = post && {
  view: msg.view,
  notice: watch.notice,
  post,
  payload: post,
  headers: { 'content-type': 'application/json' },
  requestTimeout: 10000,
}

if (!ok) {
  node.status({ fill: 'red', shape: 'ring', text: `${msg.view}: fetch failed (${msg.statusCode}) at ${time}` })
  node.warn(`${msg.view}: leaderboard fetch failed (${msg.statusCode}), ${watch.state.failures} in a row, state unchanged`)
  return [null, notice]
}

const key = `top_${msg.view}`
const { action, state, event } = watcher.decide({
  saved: flow.get(key, 'file'),
  entries: msg.payload.entries,
  view: msg.view,
})
const alert = watcher.ALERTS.includes(action)
node.status({ fill: alert ? 'yellow' : 'green', shape: 'dot', text: `${msg.view}: ${action} at ${time}` })
node.log(`${msg.view}: ${action}`)

if (action === 'none') return [null, notice]
// No alert: save now. An alert saves only once Discord accepts it.
if (!alert) {
  flow.set(key, state, 'file')
  return [null, notice]
}
return [{ view: msg.view, stateKey: key, nextState: state, event }, notice]

// The AI step: rule flags, then the Messages API request. The request is
// built in the repo (automation/watcher/claude.js); Claude sees figures
// only, never a player's name.
const watcher = global.get('watcher')
msg.flags = watcher.ruleFlags(msg.event)
msg.url = watcher.MESSAGES_URL
msg.headers = {
  'content-type': 'application/json',
  'x-api-key': env.get('ANTHROPIC_API_KEY'),
  'anthropic-version': watcher.API_VERSION,
}
msg.payload = watcher.claudeRequest(watcher.claudeInput(msg.event, msg.flags))
msg.requestTimeout = 30000
return msg

// Rule flags plus Claude's verdict give the label and the post. Without a
// verdict (an error, a refusal, bad JSON) the rules alone decide.
const watcher = global.get('watcher')
const verdict = msg.statusCode === 200 ? watcher.parseVerdict(msg.payload) : null
if (verdict) {
  const usage = msg.payload.usage ?? {}
  node.log(`${msg.view}: Claude says ${verdict.label} (${usage.input_tokens} in, ${usage.output_tokens} out)`)
} else {
  node.warn(`${msg.view}: no verdict from Claude (${msg.statusCode}), the rules decide`)
}
const { label, payload } = watcher.alertPost({ event: msg.event, flags: msg.flags, verdict })
node.status({ fill: label === 'review' ? 'yellow' : 'green', shape: 'dot', text: `${msg.view}: ${label}${verdict ? '' : ' (rules only)'}` })
// A fresh message, so the API key header goes no further.
return {
  view: msg.view,
  stateKey: msg.stateKey,
  nextState: msg.nextState,
  event: msg.event,
  flags: msg.flags,
  verdict,
  label,
  // Kept for a retry: the http request node replaces payload with the reply.
  post: payload,
  payload,
  headers: { 'content-type': 'application/json' },
  requestTimeout: 10000,
}

// Save the new #1 only once Discord accepted the post, so a failed post
// is tried again at the next check. A 429 is retried once, after the wait
// Discord asks for (automation/watcher/retry.js).
const watcher = global.get('watcher')
const what = msg.event ? msg.event.kind : `watchdog ${msg.notice}`
const time = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })

if (msg.statusCode >= 200 && msg.statusCode < 300) {
  if (msg.stateKey) flow.set(msg.stateKey, msg.nextState, 'file')
  node.status({ fill: 'green', shape: 'dot', text: `${msg.view}: posted ${what} at ${time}` })
  node.log(`${msg.view}: posted ${what}${msg.retried ? ' after a retry' : ''}`)
  return null
}

const waitMs = msg.retried ? null : watcher.retryDelayMs(msg)
if (waitMs !== null) {
  node.status({ fill: 'yellow', shape: 'ring', text: `${msg.view}: rate-limited, retrying in ${Math.ceil(waitMs / 1000)} s` })
  node.log(`${msg.view}: Discord rate-limited ${what}, retrying in ${waitMs} ms`)
  const retry = {
    view: msg.view,
    stateKey: msg.stateKey,
    nextState: msg.nextState,
    event: msg.event,
    notice: msg.notice,
    label: msg.label,
    url: msg.url,
    post: msg.post,
    payload: msg.post,
    headers: { 'content-type': 'application/json' },
    requestTimeout: 10000,
    retried: true,
  }
  setTimeout(() => node.send(retry), waitMs)
  return null
}

node.status({ fill: 'red', shape: 'ring', text: `${msg.view}: post failed (${msg.statusCode}) at ${time}` })
node.warn(`${msg.view}: Discord post of ${what} failed (${msg.statusCode})${msg.stateKey ? ', will retry at the next check' : ''}`)
return null

// Forget the fixture board's saved #1 and watchdog count, so Fixture 1
// seeds it again.
flow.set('top_fixture', undefined, 'file')
flow.set('watchdog_fixture', undefined, 'file')
node.status({ fill: 'grey', shape: 'dot', text: 'fixture state cleared' })
return null
